import json
with open('obj/project.assets.json') as f:
    d = json.load(f)
for tfm, pkgs in d.get('targets', {}).items():
    for pkg, info in pkgs.items():
        fr = info.get('frameworkReferences')
        if fr and isinstance(fr, list):
            print(f'{pkg} -> {fr}')
        elif fr and isinstance(fr, dict):
            print(f'{pkg} -> {list(fr.keys())}')
"

